use super::Route;

/// Prevents users/autogenerated hashes from using paths like
/// index.html/404.html/styles.css/robots.txt/etc...
/// Since the path is the primary-key, this is an easy blocker.
pub struct Reserved(pub(super) String);

impl From<Reserved> for Route {
	fn from(value: Reserved) -> Self {
		Route::Reserved(value)
	}
}
